    views: row.view_count ?? 0,
    likes: row.like_count ?? 0,
    commentsCount: row.comment_count ?? 0,
    tags,
    likedByCurrentUser:
      Boolean(currentUserId) &&
      (row.post_likes ?? []).some(like => like.user_id === currentUserId),
    isAiGenerated: row.is_ai_generated === true,
  };
};

